INSERT INTO public.categories (name, slug, description) VALUES ('Analytical Chemicals', 'analytical-chemicals', 'Analytical grade reagents, AR/HPLC solvents, volumetric standards and indicators sourced from trusted manufacturers and supplied with certificates of analysis. Suitable for teaching laboratories, quality control units, research institutions and industry.');
INSERT INTO public.categories (name, slug, description) VALUES ('Laboratory Equipment', 'laboratory-equipment', 'Benchtop and floor-standing laboratory instruments — from balances and centrifuges to incubators, spectrophotometers and water baths — with installation guidance and after-sales technical support nationwide.');
INSERT INTO public.categories (name, slug, description) VALUES ('Glassware', 'glassware', 'Class A and Class B borosilicate 3.3 glassware for volumetric, distillation and general bench work. Individually inspected, packed for safe transit and available in bulk quantities for institutional orders.');
INSERT INTO public.categories (name, slug, description) VALUES ('Household Chemicals', 'household-chemicals', 'Detergent bases, disinfectants, sanitisers and cleaning concentrates supplied in retail and bulk pack sizes for households, schools, hotels and facility management companies.');
INSERT INTO public.categories (name, slug, description) VALUES ('Industrial Chemicals', 'industrial-chemicals', 'Bulk industrial chemistry for water treatment, mining, food processing and manufacturing — supplied in drums, sacks and IBCs with safety data sheets and scheduled delivery across Ghana.');
INSERT INTO public.categories (name, slug, description) VALUES ('Furniture & Fittings', 'furniture-fittings', 'Chemical-resistant laboratory furniture and fit-out — island benches, wall benches, fume cupboards, safety cabinets and sinks — designed, supplied and installed for schools, hospitals and industrial laboratories.');
INSERT INTO public.categories (name, slug, description) VALUES ('Personal Protective Equipment', 'personal-protective-equipment', 'Certified PPE for laboratory, clinical and industrial use — lab coats, gloves, eye protection, respirators and safety footwear — available in institutional pack sizes.');
INSERT INTO public.categories (name, slug, description) VALUES ('Consumables', 'consumables', 'Plastics, filtration media, sample containers and other single-use laboratory consumables kept in stock for fast repeat supply.');
INSERT INTO public.products (name, slug, sku, description, unit_label, price, stock_quantity, is_active) SELECT 'Sulphuric Acid 98% AR Grade', 'ac-001', 'AC-001', 'Analytical reagent grade sulphuric acid for titrimetry, digestion and general analytical use. Supplied with a batch certificate of analysis. [Acids & Bases] Specs — Assay: ≥ 98%; Grade: Analytical Reagent (AR); CAS No.: 7664-93-9; Pack size: 2.5 L amber bottle | Brand: LabChem', '2.5 L bottle', 420, 100, true WHERE NOT EXISTS (SELECT 1 FROM public.products WHERE slug = 'ac-001');
